package com.example.demo.adapters.jdbc;

import com.example.demo.domain.Article;
import com.example.demo.repository.ArticleRepository;
import java.util.List;
import java.util.Optional;
import java.util.UUID;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Repository;

@Repository
public final class JdbcArticleRepository implements ArticleRepository {

    private final JdbcClient jdbc;

    public JdbcArticleRepository(JdbcClient jdbc) {
        this.jdbc = jdbc;
    }

    @Override
    public Optional<Article> findById(UUID id) {
        return jdbc.sql("select id, title, body from articles where id = :id")
                .param("id", id)
                .query(Article.class)
                .optional();
    }

    @Override
    public List<Article> findAll() {
        return jdbc.sql("select id, title, body from articles order by id")
                .query(Article.class)
                .list();
    }

    @Override
    public Article save(Article value) {
        return jdbc.sql("insert into articles (id, title, body) values (:id, :title, :body) on conflict (id) do update set title = excluded.title, body = excluded.body returning id, title, body")
                .param("id", value.id())
                .param("title", value.title())
                .param("body", value.body())
                .query(Article.class)
                .single();
    }

    @Override
    public boolean deleteById(UUID id) {
        return jdbc.sql("delete from articles where id = :id")
                .param("id", id)
                .update() > 0;
    }
}
